import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%82%B9%E3%82%BF%E3%82%A4%E3%83%A9%E3%82%B9.html","title":"スタイラス","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.42,"words":126},"filePathRelative":"スタイラス.md"}`),a={name:`スタイラス.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="スタイラス" tabindex="-1"><a class="header-anchor" href="#スタイラス"><span>スタイラス</span></a></h1><p>主に<a href="./Supernote.html">Supernote</a>のスタイラスに関する事を書く。</p><h2 id="emrスタイラス-pen-plus-one" tabindex="-1"><a class="header-anchor" href="#emrスタイラス-pen-plus-one"><span>EMRスタイラス Pen Plus One</span></a></h2><p>セラミックnibで評判が良くて安い以下のスタイラスを購入。3999円だった。</p><p><a href="https://link.amazon/B02NavSvZ" target="_blank" rel="noopener noreferrer">amazon: PL1A EMRスタイラスペン</a></p><h3 id="購入-2026-10-13-火" tabindex="-1"><a class="header-anchor" href="#購入-2026-10-13-火"><span>購入 2026-10-13 (火)</span></a></h3><p>redditとかではPen Plus Oneとか言われていて箱にもそう書いてあるがAmazonのページでは書いてないので一瞬これか不安だったが、届いた箱にはPen Plus Oneと書いてあった。</p><p>書き味は固くてペン先も細くて、BOOXのペンとは全然違う。ただこちらの方がいいのか？と言われると少し悩むな。 これもいいんだが、BOOXのペンも悪くないよなぁ、と比較して思う。</p><p>少し細すぎて持ちにくい。BOOXのペンくらい太さがある方が持ちやすい気もする。何か巻いてもいいが、書きにくいかというとそうでも無いので悩むな。</p><p>わざわざ買わなくても良かったが、二つを比べるのは楽しいのでそういう遊びとしては良いかもしれない。</p><p>追記: しばらく使い分けていた所、やはりこちらのペンの方がいいという気がしてきた。だいぶいいね、これ！</p><h3 id="_100均一のマーカーのガワをつける-2026-10-18-日" tabindex="-1"><a class="header-anchor" href="#_100均一のマーカーのガワをつける-2026-10-18-日"><span>100均一のマーカーのガワをつける 2026-10-18 (日)</span></a></h3><p>少し細すぎて<a href="./Supernote.html">Supernote</a>のスリーブへのおさまりも悪いので、100均のマーカーを買ってきて中を抜いてペンを挿した。 ドリルの歯で少し広げる必要あり。</p><p>持ち味も良くなり、書くフィーリングは凄く良くなった。 ただキャップから抜くのが少し固い。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};